# ---- US-203 Sort ----------------------------------------------------------

def _seed_three(actions):
    for title in ("banana", "Apple", "cherry"):
        actions.create_post(title, "c")
        time.sleep(0.005)


def test_sort_title_ascending_and_descending(make_client):
    client, actions = make_client()
    _seed_three(actions)
    asc = client.get("/?sort=title_asc").get_data(as_text=True)
    desc = client.get("/?sort=title_desc").get_data(as_text=True)
    assert asc.index("Apple") < asc.index("banana") < asc.index("cherry")
    assert desc.index("cherry") < desc.index("banana") < desc.index("Apple")


def test_sort_date_newest_and_oldest_first(make_client):
    client, actions = make_client()
    _seed_three(actions)
    newest = client.get("/?sort=date_desc").get_data(as_text=True)
    oldest = client.get("/?sort=date_asc").get_data(as_text=True)
    assert newest.index("cherry") < newest.index("Apple") < newest.index("banana")
    assert oldest.index("banana") < oldest.index("Apple") < oldest.index("cherry")


def test_sort_unknown_value_falls_back_to_default(make_client):
    client, actions = make_client()
    actions.create_post("One", "c")
    assert client.get("/?sort=bogus;DROP TABLE post").status_code == 200


def test_sort_and_search_combine(make_client):
    client, actions = make_client()
    for title in ("b match", "a match", "c other"):
        actions.create_post(title, "c")
    html = client.get("/?q=match&sort=title_asc").get_data(as_text=True)
    assert html.index("a match") < html.index("b match")
    assert "c other" not in html


def test_sort_control_lists_all_options(make_client):
    client, _ = make_client()
    html = client.get("/").get_data(as_text=True)
    for value in ("date_desc", "date_asc", "title_asc", "title_desc"):
        assert f'value="{value}"' in html


# ---- US-301 Create --------------------------------------------------------

def test_create_requires_login(client):
    assert client.get("/blog/create").status_code == 302


def test_create_link_visible_only_when_logged_in(client, make_client):
    assert "Create Blog" not in client.get("/auth/login").get_data(as_text=True)
    logged_in, _ = make_client()
    assert "Create Blog" in logged_in.get("/").get_data(as_text=True)


def test_create_assigns_author_and_redirects_to_post(app, make_client):
    client, actions = make_client("alice")
    response = actions.create_post("My title", "My content")
    assert response.status_code == 302
    pid = post_id_from(response)
    with app.app_context():
        row = get_db().execute(
            "SELECT u.username FROM post p JOIN user u ON u.id = p.author_id WHERE p.id = ?", (pid,)
        ).fetchone()
    assert row["username"] == "alice"
    assert "My title" in client.get(f"/blog/{pid}").get_data(as_text=True)


def test_create_validation(make_client):
    _, actions = make_client()
    assert actions.create_post("", "content").status_code == 400
    assert actions.create_post("title", "").status_code == 400
    assert actions.create_post("   ", "content").status_code == 400
    assert actions.create_post("title", "   \n ").status_code == 400
    assert actions.create_post("t" * 151, "content").status_code == 400
    assert actions.create_post("title", "c" * 10_001).status_code == 400
    assert actions.create_post("t" * 150, "c" * 10_000).status_code == 302


