def test_edit_form_prepopulated(make_client):
    client, actions = make_client()
    pid = post_id_from(actions.create_post("Original", "Original body"))
    html = client.get(f"/blog/{pid}/edit").get_data(as_text=True)
    assert 'value="Original"' in html and "Original body" in html


def test_edit_updates_content_and_modified_timestamp(app, make_client):
    client, actions = make_client()
    pid = post_id_from(actions.create_post("Original", "body"))
    time.sleep(0.02)
    response = actions.post(f"/blog/{pid}/edit", {"title": "Updated", "content": "new body"})
    assert response.status_code == 302
    with app.app_context():
        row = get_db().execute("SELECT * FROM post WHERE id = ?", (pid,)).fetchone()
    assert row["title"] == "Updated" and row["content"] == "new body"
    assert row["updated_at"] > row["created_at"]


def test_edit_validation_error(make_client):
    _, actions = make_client()
    pid = post_id_from(actions.create_post("Original", "body"))
    assert actions.post(f"/blog/{pid}/edit", {"title": "", "content": "x"}).status_code == 400


def test_edit_by_non_author_forbidden_and_data_unchanged(app, make_client):
    _, a_actions = make_client("alice")
    bob, b_actions = make_client("bob")
    pid = post_id_from(a_actions.create_post("Alice's", "secret"))
    assert bob.get(f"/blog/{pid}/edit").status_code == 403
    assert b_actions.post(f"/blog/{pid}/edit", {"title": "Hacked", "content": "x"}).status_code == 403
    with app.app_context():
        row = get_db().execute("SELECT title FROM post WHERE id = ?", (pid,)).fetchone()
    assert row["title"] == "Alice's"


