def test_delete_shows_confirmation_page_first(app, make_client):
    client, actions = make_client()
    pid = post_id_from(actions.create_post("Doomed", "content"))
    response = client.get(f"/blog/{pid}/delete")
    assert response.status_code == 200
    assert "Are you sure" in response.get_data(as_text=True)
